"""Sidecar artifacts for document interpretations generated by models."""

from __future__ import annotations

import json
from dataclasses import asdict, dataclass, field
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Iterable, Literal

from dataset_generation.jsonl import append_jsonl_object, read_jsonl_objects


InterpretationKind = Literal["visual", "textual"]


@dataclass(frozen=True)
class InterpretationRecord:
    record_id: str
    kind: InterpretationKind
    text: str
    model: str
    prompt_id: str
    prompt_version: str
    metadata: dict[str, Any] = field(default_factory=dict)


def default_interpretation_dir(data_dir: str | Path, run_id: str) -> Path:
    return Path(data_dir) / "interim" / "interpretations" / run_id


def write_interpretations(
    records: Iterable[InterpretationRecord],
    output_dir: str | Path,
    run_metadata: dict[str, Any] | None = None,
) -> Path:
    """Write compact interpretation JSONL keyed by base dataset record_id."""
    output_path = Path(output_dir)
    output_path.mkdir(parents=True, exist_ok=True)
    materialized = [asdict(record) for record in records]

    (output_path / "interpretations.jsonl").write_text(
        "\n".join(json.dumps(record, sort_keys=True, ensure_ascii=False) for record in materialized)
        + ("\n" if materialized else ""),
        encoding="utf-8",
    )
    metadata = {
        "created_at_utc": datetime.now(timezone.utc).isoformat(),
        "record_count": len(materialized),
        **(run_metadata or {}),
    }
    (output_path / "metadata.json").write_text(
        json.dumps(metadata, indent=2, sort_keys=True, ensure_ascii=False),
        encoding="utf-8",
    )
    return output_path


def interpretation_key(record: InterpretationRecord | dict[str, Any]) -> tuple[str, str, str, str, str]:
    """Stable key used for resumable interpretation generation."""
    if isinstance(record, InterpretationRecord):
        return (record.record_id, record.kind, record.model, record.prompt_id, record.prompt_version)
    return (
        str(record["record_id"]),
        str(record["kind"]),
        str(record["model"]),
        str(record["prompt_id"]),
        str(record["prompt_version"]),
    )


def read_completed_interpretation_keys(
    artifact_dir: str | Path,
    *,
    kind: InterpretationKind,
    model: str,
    prompt_id: str,
    prompt_version: str,
) -> set[tuple[str, str, str, str, str]]:
    """Read existing JSONL sidecars and return completed generation keys."""
    output_path = Path(artifact_dir)
    keys: set[tuple[str, str, str, str, str]] = set()
    for data_path in sorted(output_path.glob("interpretations*.jsonl")):
        for row in read_jsonl_objects(data_path):
            if (
                row.get("kind") == kind
                and row.get("model") == model
                and row.get("prompt_id") == prompt_id
                and row.get("prompt_version") == prompt_version
            ):
                keys.add(interpretation_key(row))
    return keys


def append_interpretation_record(record: InterpretationRecord, output_file: str | Path) -> None:
    """Append one interpretation record as JSONL."""
    append_jsonl_object(output_file, asdict(record), sort_keys=True)


def append_failure_record(row: dict[str, Any], output_file: str | Path) -> None:
    """Append one failed generation row as JSONL."""
    append_jsonl_object(output_file, row, sort_keys=True)


def read_interpretations(artifact_dir: str | Path) -> list[dict[str, Any]]:
    data_path = Path(artifact_dir) / "interpretations.jsonl"
    try:
        return read_jsonl_objects(data_path)
    except FileNotFoundError as exc:
        raise FileNotFoundError(f"No interpretations.jsonl found in {artifact_dir}") from exc
